subservice_1.sdl:
type Product @key(selectionSet: "{ id }") {
  id: ID!
  name: String!
  price: Float!
}

type Query {
  product(id: ID!): Product @merge(keyField: "id", keyArg: "id")
  products: [Product!]!
}

subservice_2.sdl:
type Product @key(selectionSet: "{ id }") {
  id: ID!
  stock: Int!
  warehouse: String!
}

type Query {
  productInventory(id: ID!): Product @merge(keyField: "id", keyArg: "id")
}
